head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil00120";

// TODO Stage2: 세션 키 실환경 확인(회신 11항 · user-info 계약에 없는 키) — session.user.usrTpCd

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_sessionFill();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil00120.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_isurCd", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["isurCd"] ?? ""); } },
        { childId: "ipt_fssUnqNo", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["fssUnqNo"] ?? ""); } },
        { childId: "ipt_txtisurCdVote", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["isurCd"] ?? ""); } },
        { childId: "ipt_txtfssUnqNoVote", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["fssUnqNo"] ?? ""); } },
        { childId: "ipt_txtcomNmVote", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["comNm"] ?? ""); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

// 세션 사용자 결선 (어휘 session_attribute 1건 — gcc $c.session.getUserInfo)

/**
 * @method
 * @name init_sessionFill
 * @description 초기화 — session Fill
 * @returns {void}
 * @hidden N
 */
scwin.init_sessionFill = function () {
    const names = ["usrTpCd"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil00120' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_80_onclick
 * @description img_80 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_80_onclick = function(e){
    try {
        scwin.findCompanyVote()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00120.img_80_onclick' }); }
};

/**
 * @method
 * @name img_111_onclick
 * @description img_111 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_111_onclick = function(e){
    try {
        scwin.findCompany()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00120.img_111_onclick' }); }
};

/**
 * @method
 * @name img_133_onclick
 * @description img_133 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_133_onclick = async function(e){
    try {
        await scwin.goWrite()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil00120.img_133_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_documentWrite_exmpt
 * @description document Write exmpt 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_documentWrite_exmpt = async function () {
    const sbmOptions = {
        id: "tx_fn_documentWrite_exmpt",
        method: "post",
        action: "/submission/disclosure.do?method=searchDisclosureDocument&reqObjDocAcpNo=",
        ref: "dma_documentWriteExmptReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_documentWrite
 * @description document Write 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_documentWrite = async function () {
    const sbmOptions = {
        id: "tx_fn_documentWrite",
        method: "post",
        action: "/submission/disclosure.do?method=searchDisclosureDocument",
        ref: "dma_documentWriteReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_goWrite
 * @description go Write 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_goWrite = async function () {
    const sbmOptions = {
        id: "tx_fn_goWrite",
        method: "post",
        action: "/submission/disclosurereg.do?method=registerDisclosure&reqObjDocAcpNo=",
        ref: "dma_goWriteReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name findCompany
 * @description find Company 처리
 * @returns {void}
 * @hidden N
 */
scwin.findCompany = function () {
    const corpSearchURL = '/jldfil00033/jldfil00033.xml?method=loadInitPage&ldMktTpCd=' + dma_disclosureVo.get("ldMktTpCd") + '';
    (Promise.resolve($c.win.openPopup(corpSearchURL, { id: "corpWin", scrollbars: false, resizable: false, width: "600", height: "570", type: "pageFramePopup" }, {})).then(function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } }), { closed: false, focus: function () {}, close: function () { $c.win.getScope().closePopup("corpWin"); this.closed = true; } });
};

/**
 * @method
 * @name findCompanyVote
 * @description find Company Vote 처리
 * @returns {void}
 * @hidden N
 */
scwin.findCompanyVote = function () {
    const corpSearchURL = '/submission/voterghtExerDisclsCorpList.do?method=loadInitPageForVoterghtExer';
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    (Promise.resolve($c.win.openPopup((function (__u) { const __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(corpSearchURL), { id: "asstcomWin", scrollbars: false, resizable: false, width: "600", height: "550", type: "pageFramePopup" }, {})).then(function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } }), { closed: false, focus: function () {}, close: function () { $c.win.getScope().closePopup("asstcomWin"); this.closed = true; } });
};

/**
 * @method
 * @name setCorpInfo
 * @description set Corp Info 처리
 * @param {String} isurCd isurCd
 * @param {String} kisComCd kisComCd
 * @param {String} repIsuSrtCd repIsuSrtCd
 * @param {String} comNm comNm
 * @param {*} comAbbrv comAbbrv
 * @param {*} isurSymbl isurSymbl
 * @param {*} fssUnqNo fssUnqNo
 * @param {*} comEngAbbrv comEngAbbrv
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfo = function (isurCd, kisComCd, repIsuSrtCd, comNm, comAbbrv, isurSymbl, fssUnqNo, comEngAbbrv) {
    $c.util.getComponent("ipt_txtisurCd").setValue(isurCd);
    $c.util.getComponent("ipt_txtfssUnqNo").setValue(fssUnqNo);
    $c.util.getComponent("ipt_txtcomNm").setValue(comAbbrv);
    $c.util.getComponent('dma_documentWriteExmptReq').set('tgtIsuSrtCd', repIsuSrtCd);
    $c.util.getComponent('dma_documentWriteExmptReq').set('tgtIsuSrtCd', repIsuSrtCd);
    $c.util.getComponent('dma_documentWriteExmptReq').set('chkPop', 'Y');
    $c.util.getComponent('dma_documentWriteExmptReq').set('tgtComEngNm', comEngAbbrv);
};

/**
 * @method
 * @name setCorpInfoVote
 * @description set Corp Info Vote 처리
 * @param {String} isurCd isurCd
 * @param {*} fssUnqNo fssUnqNo
 * @param {String} comNm comNm
 * @param {String} comEngNm comEngNm
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfoVote = function (isurCd, fssUnqNo, comNm, comEngNm) {
    $c.util.getComponent("ipt_txtisurCdVote").setValue(isurCd);
    $c.util.getComponent("ipt_txtfssUnqNoVote").setValue(fssUnqNo);
    $c.util.getComponent("ipt_txtcomNmVote").setValue(comNm);
    $c.util.getComponent('dma_documentWriteExmptReq').set('tgtComEngNmVote', comEngNm);
    $c.util.getComponent('dma_documentWriteExmptReq').set('chkPop', 'Y');
};

/**
 * @method
 * @name documentWriteExmpt
 * @description document Write Exmpt 처리
 * @param {*} reqObjDocAcpNo reqObjDocAcpNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.documentWriteExmpt = async function (reqObjDocAcpNo) {
    (document.corpForm || { elements: [] }).action = '/submission/disclosure.do?method=searchDisclosureDocument&reqObjDocAcpNo=' + reqObjDocAcpNo;
    await scwin.tx_fn_documentWrite_exmpt();
};

/**
 * @method
 * @name registerProcessExmpt
 * @description register Process Exmpt 처리
 * @param {*} applNo applNo
 * @param {*} docNo docNo
 * @param {String} formCd formCd
 * @param {*} formVer formVer
 * @param {String} wrtrptMaindocTpCd wrtrptMaindocTpCd
 * @param {*} method method
 * @param {*} reqObjDocAcpNo reqObjDocAcpNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.registerProcessExmpt = async function (applNo, docNo, formCd, formVer, wrtrptMaindocTpCd, method, reqObjDocAcpNo) {
    $c.util.getComponent('dma_documentWriteExmptReq').set('applNo', applNo);
    if (applNo.length === 14) {
        await scwin.documentWriteExmpt(reqObjDocAcpNo);
    } else {
        await scwin.registerMessage('문서불러오기에 실패하였습니다. 잠시후 다시 해주시기 바랍니다.');
    }
};

/**
 * @method
 * @name documentWrite
 * @description document Write 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.documentWrite = async function () {
    (document.corpForm || { elements: [] }).action = '/submission/disclosure.do?method=searchDisclosureDocument';
    await scwin.tx_fn_documentWrite();
};

/**
 * @method
 * @name registerProcess
 * @description register Process 처리
 * @param {*} applNo applNo
 * @param {*} docNo docNo
 * @param {String} formCd formCd
 * @param {*} formVer formVer
 * @param {String} wrtrptMaindocTpCd wrtrptMaindocTpCd
 * @param {*} method method
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.registerProcess = async function (applNo, docNo, formCd, formVer, wrtrptMaindocTpCd, method) {
    $c.util.getComponent('dma_documentWriteExmptReq').set('applNo', applNo);
    if (applNo.length === 14) {
        await scwin.documentWrite();
    } else {
        await scwin.registerMessage('문서불러오기에 실패하였습니다. 잠시후 다시 해주시기 바랍니다.');
    }
};

/**
 * @method
 * @name registerMessage
 * @description register Message 처리
 * @param {String} msg 항목명
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.registerMessage = async function (msg) {
    await $c.win.alert(msg);
};

/**
 * @method
 * @name goWrite
 * @description go Write 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goWrite = async function () {
    if (($c.util.getComponent('ipt_txtisurCd').getValue() == null ? '' : String($c.util.getComponent('ipt_txtisurCd').getValue())) === '' || ($c.util.getComponent('ipt_txtfssUnqNo').getValue() == null ? '' : String($c.util.getComponent('ipt_txtfssUnqNo').getValue())) === '' || ($c.util.getComponent('ipt_txtcomNm').getValue() == null ? '' : String($c.util.getComponent('ipt_txtcomNm').getValue())) === '' || $c.util.getComponent('dma_documentWriteExmptReq').get('chkPop') === '') {
        await $c.win.alert('대상회사를 선택하십시요');
        return;
    }
    $c.util.getComponent('dma_documentWriteExmptReq').set('tgtIsurCd', $c.util.getComponent('ipt_txtisurCd').getValue());
    $c.util.getComponent('dma_documentWriteExmptReq').set('tgtFssUnqNo', $c.util.getComponent('ipt_txtfssUnqNo').getValue());
    $c.util.getComponent('dma_documentWriteExmptReq').set('tgtComNm', $c.util.getComponent('ipt_txtcomNm').getValue());
    $c.util.getComponent('dma_documentWriteExmptReq').set('tgtIsurCd', $c.util.getComponent('ipt_txtisurCd').getValue());
    $c.util.getComponent('dma_documentWriteExmptReq').set('tgtFssUnqNo', $c.util.getComponent('ipt_txtfssUnqNo').getValue());
    $c.util.getComponent('dma_documentWriteExmptReq').set('tgtComNm', $c.util.getComponent('ipt_txtcomNm').getValue());
    if ((String(($c.session.getUserInfo("usrTpCd")) == null ? '' : ($c.session.getUserInfo("usrTpCd"))).indexOf('$' + '{') >= 0 ? '' : String(($c.session.getUserInfo("usrTpCd")) == null ? '' : ($c.session.getUserInfo("usrTpCd")))) === '4' && (('99840' === $c.util.getComponent('ipt_formCd').getValue()) || ('70970' === $c.util.getComponent('ipt_formCd').getValue()))) {
        (document.disclosureFrm || { elements: [] }).action = '/submission/disclosurereg.do?method=registerDisclosure&reqObjDocAcpNo=' + $c.util.getComponent('dma_documentWriteExmptReq').get('reqObjDocAcpNo');
        (document.disclosureFrm || { elements: [] }).target = 'tempSaveFrame';
        await scwin.tx_fn_goWrite();
    } else {
        (document.disclosureFrm || { elements: [] }).action = '/submission/disclosurereg.do?method=registerDisclosure';
        (document.disclosureFrm || { elements: [] }).target = 'tempSaveFrame';
        await scwin.tx_fn_goWrite();
    }
};
